'use strict';
const OBSTACLES=[{x:420,y:360,radius:48},{x:520,y:650,radius:52},{x:1020,y:370,radius:52},{x:1080,y:660,radius:48},{x:590,y:170,radius:32},{x:915,y:830,radius:35}];
const BUSHES=[{x:520,y:410,w:100,h:58},{x:945,y:590,w:105,h:65},{x:430,y:730,w:100,h:60},{x:1090,y:285,w:100,h:60}];
function inBush(e){return BUSHES.some(b=>Math.abs(e.x-b.x)<b.w/2&&Math.abs(e.y-b.y)<b.h/2);}
function visibleToTeam(e,team){if(e.team===team||e.type!=='hero'||!inBush(e))return true;if(game.time-(e.lastDamaged??-10)<2)return true;return game.entities.some(a=>!a.dead&&a.team===team&&a.type==='hero'&&distance(a,e)<175);}
function fountainSpawn(e){const h=home(e.team),slot=Math.max(0,Object.keys(POSITIONS).indexOf(e.position)),angle=-1.45+slot*.45,sign=e.team===0?1:-1;return {x:h.x+Math.cos(angle)*98*sign,y:h.y+Math.sin(angle)*98*sign};}
const basicLoadout=applyLoadout;applyLoadout=function(...args){basicLoadout(...args);Object.assign(args[0],fountainSpawn(args[0]));};
const basicHero=hero;
hero=function(...args){return {...basicHero(...args),mana:400,maxMana:400,unstoppable:0,qCombo:0,channel:0};};
const basicEnemies=enemies;
enemies=function(e,range,includeNeutral=false){return basicEnemies(e,range,includeNeutral).filter(t=>visibleToTeam(t,e.team));};
const basicMove=move;
move=function(e,x,y,dt){const before={x:e.x,y:e.y};if(!e.player&&!e.remoteHuman||e.destination){const goal={x,y};if(!e.navigation||distance(e.navigation.goal,goal)>70){e.navigation={goal,path:findDetour(e,goal,OBSTACLES,e.radius)};}while(e.navigation.path.length&&distance(e,e.navigation.path[0])<8)e.navigation.path.shift();if(e.navigation.path.length){x=e.navigation.path[0].x;y=e.navigation.path[0].y;}else e.navigation=null;}else e.navigation=null;basicMove(e,x,y,dt);for(const o of OBSTACLES){const dx=e.x-o.x,dy=e.y-o.y,r=o.radius+e.radius,d=Math.hypot(dx,dy);if(d<r){const length=d||1;e.x=o.x+(d?dx/length:Math.sign(before.x-o.x)||1)*r;e.y=o.y+(d?dy/length:0)*r;}}};
function safeLanding(p){for(const o of OBSTACLES){const dx=p.x-o.x,dy=p.y-o.y,r=o.radius+p.radius,d=Math.hypot(dx,dy);if(d<r){p.x=o.x+(dx/(d||1)||1)*r;p.y=o.y+dy/(d||1)*r;}}p.x=Math.max(45,Math.min(WIDTH-45,p.x));p.y=Math.max(45,Math.min(HEIGHT-45,p.y));}
function aimFor(p,range=450){const options=enemies(p,range,true).filter(t=>t.type!=='base'||baseOpen(t.team)).sort((a,b)=>(a.type==='hero'?0:1)-(b.type==='hero'?0:1)||distance(p,a)-distance(p,b));const t=options[0];if(t)return {x:t.x,y:t.y};if(p.facing)return {x:p.x+p.facing.x*range,y:p.y+p.facing.y*range};return home(1-p.team);}
function limitAim(p,aim,range){const dx=aim.x-p.x,dy=aim.y-p.y,d=Math.hypot(dx,dy)||1,m=Math.min(d,range);return {x:Math.max(45,Math.min(WIDTH-45,p.x+dx/d*m)),y:Math.max(45,Math.min(HEIGHT-45,p.y+dy/d*m))};}
function setAction(p,kind,aim){p.actionAnim=kind;p.actionAt=(p.actionAt||0)+1;if(aim){const dx=aim.x-p.x,dy=aim.y-p.y,d=Math.hypot(dx,dy)||1;p.facing={x:dx/d,y:dy/d};}}
function stun(e,seconds){if(!(e.unstoppable>0))e.stun=Math.max(e.stun||0,seconds);}
function skillInfo(p,key){if(p.def.id==='arcanist')return key==='q'?{mode:'direction',range:520,radius:55}:key==='w'?{mode:'area',range:300,radius:95}:{mode:'self',range:0,radius:p.range};if(key==='w')return {mode:'direction',range:210,radius:20};if(key==='q'&&['ranger','shade','sentinel'].includes(p.def.id))return {mode:'direction',range:p.def.id==='ranger'?430:p.def.id==='shade'?180:185,radius:p.def.id==='ranger'?35:185};return {mode:'self',range:0,radius:p.def.id==='oracle'?(key==='q'?300:450):p.def.id==='shade'?170:p.def.id==='bulwark'?185:200};}
function spellDamage(target,amount,source){if(['tower','base'].includes(target.type))return;return damage(target,amount,source);}
function hitCone(p,aim,radius,amount,angle=.2){const dx=aim.x-p.x,dy=aim.y-p.y,d=Math.hypot(dx,dy)||1;for(const t of enemies(p,radius,true).filter(t=>!['tower','base'].includes(t.type))){const td=Math.hypot(t.x-p.x,t.y-p.y)||1;if(((t.x-p.x)*dx+(t.y-p.y)*dy)/(td*d)>=angle)damage(t,amount,p);}}
const baseDamageWithAggro=damage;
damage=function(target,amount,source){
  if(target.type==='hero'&&source.type==='hero'&&source.team!==target.team)for(const tower of game.entities.filter(e=>e.type==='tower'&&!e.dead&&e.team===target.team&&distance(e,target)<e.range&&distance(e,source)<e.range)){tower.aggroTarget=source.id;tower.aggroUntil=game.time+2.5;}
  if(target.type==='tower'&&source.type==='hero'&&!game.entities.some(e=>e.type==='minion'&&!e.dead&&e.team===source.team&&distance(e,target)<target.range))amount*=.4;
  return baseDamageWithAggro(target,amount,source);
};
const basicStrike=strike;
strike=function(p,t){if(p.type!=='hero'){
  if(p.type==='tower'&&p.attack<=0&&t){const oldDamage=p.damage;p.towerShots=p.towerTarget===t.id?(p.towerShots||0)+1:0;p.towerTarget=t.id;if(t.type==='hero')p.damage*=Math.min(2.4,1+p.towerShots*.3);basicStrike(p,t);p.damage=oldDamage;return;}
  return basicStrike(p,t);
}if(p.dead||p.attack>0||p.stun>0||p.channel>0||!t||t.dead)return;const ranged=p.range>150;p.attack=(p.def.id==='ranger'?.75:1)*(p.rage>0?.48:1);const amount=p.damage*(p.buff>0?1.2:1)*(p.rage>0?1.4:1)*(game.teamBuffs?.[p.team]>0&&['tower','base'].includes(t.type)?1.25:1);setAction(p,'attack',t);p.targetId=t.id;p.targetUntil=game.time+1.4;game.strikes ||= [];game.strikes.push({id:game.nextId++,source:p.id,target:t.id,at:game.time+(ranged?.2:.16),amount,ranged,range:p.range});effects.push({type:ranged?'bolt':'slash',fxId:'attack'+p.id+':'+p.actionAt,x:p.x,y:p.y,tx:t.x,ty:t.y,radius:p.range,color:p.team===0?BLUE:RED,life:ranged?.2:.24,max:ranged?.2:.24});if(p.player)tone(ranged?450:260);};
const basicSkill=useSkill;
useSkill=function(key,actor=null,aim=null){if(!game||game.paused||game.finished||!['q','w','e'].includes(key))return false;const p=actor||game.player;if(p.dead||p.stun>0||p.channel>0||p.cd[key]>0)return false;p.mana??=400;p.maxMana??=400;const cost=key==='w'?35:key==='q'?50:100;if(p.mana<cost){if(p.player)notify('มานาไม่พอ · กลับฐานหรือรอให้ฟื้น');return false;}aim=aim&&Number.isFinite(aim.x)&&Number.isFinite(aim.y)?aim:aimFor(p);const tint=p.team===0?BLUE:RED;let cooldown=key==='q'?6:20,ok=true;
  if(key==='q'&&p.def.id==='arcanist'){const dx=aim.x-p.x,dy=aim.y-p.y,len=Math.hypot(dx,dy)||1,tx=p.x+dx/len*520,ty=p.y+dy/len*520,delay=.45;game.casts ||= [];game.casts.push({id:game.nextId++,source:p.id,at:game.time+delay,x:p.x,y:p.y,tx,ty,line:true,radius:55,amount:(200+p.level*18)*p.spell});effects.push({type:'breathWarning',x:p.x,y:p.y,tx,ty,radius:55,color:'#b4ed70',life:delay,max:delay});setAction(p,'spell',{x:tx,y:ty});cooldown=7;}
  else if(key==='w'&&p.def.id==='arcanist'){const at=limitAim(p,aim,300);for(const t of enemies(p,430,true).filter(t=>distance(t,at)<95+t.radius)){spellDamage(t,(95+p.level*12)*p.spell,p);if(t.type==='hero'||t.type==='minion'){const dx=t.x-at.x,dy=t.y-at.y,d=Math.hypot(dx,dy)||1;t.x+=dx/d*65;t.y+=dy/d*65;safeLanding(t);if(t.type==='hero')stun(t,.4);}}effects.push({type:'ring',x:at.x,y:at.y,radius:95,color:'#b4ed70',life:.5,max:.5});setAction(p,'spell',at);cooldown=9;}
  else if(key==='e'&&p.def.id==='arcanist'){p.rage=8;p.shield=350+p.level*30;p.shieldTime=8;p.cd.q=p.cd.w=0;if(!p.dragonRangeBuff){p.range+=90;p.dragonRangeBuff=true;}setAction(p,'ultimate',aim);effects.push({type:'ring',x:p.x,y:p.y,radius:p.range,color:'#b4ed70',life:1,max:1});cooldown=24;if(p.player)notify('ปลุกมังกร · ยิงเร็วขึ้น เพิ่มระยะโจมตี และรีเซ็ตสกิล 8 วินาที');}
  else if(key==='q'&&p.def.id==='ranger'){game.projectiles ||= [];const angle=Math.atan2(aim.y-p.y,aim.x-p.x);for(const offset of [-.18,0,.18])game.projectiles.push({id:game.nextId++,source:p.id,team:p.team,x:p.x,y:p.y,dx:Math.cos(angle+offset),dy:Math.sin(angle+offset),remaining:430,speed:850,damage:(95+p.level*12)*p.spell});setAction(p,'attack',aim);}
  else if(key==='q'&&p.def.id==='shade'){const dx=aim.x-p.x,dy=aim.y-p.y,len=Math.hypot(dx,dy)||1,first=p.qCombo!==1,from={x:p.x,y:p.y};setAction(p,'attack',aim);p.x+=dx/len*180;p.y+=dy/len*180;safeLanding(p);p.destination=null;for(const t of enemies(p,150,true)){spellDamage(t,(120+p.level*15)*p.spell,p);if(first&&t.type==='hero')stun(t,.65);}effects.push({type:'shot',x:from.x,y:from.y,tx:p.x,ty:p.y,color:PURPLE,life:.3,max:.3});effects.push({type:'ring',x:p.x,y:p.y,radius:150,color:PURPLE,life:.35,max:.35});if(first){p.qCombo=1;p.comboUntil=game.time+3;p.comboReadyAt=game.time+8;cooldown=.15;}else{p.qCombo=0;cooldown=Math.max(0,p.comboReadyAt-game.time);}}
  else if(key==='e'&&p.def.id==='shade'){const t=enemies(p,380,true).filter(t=>['hero','monster','minion'].includes(t.type)).sort((a,b)=>(a.type==='hero'?0:1)-(b.type==='hero'?0:1)||distance(p,a)-distance(p,b))[0];if(!t){if(p.player)notify('ไม่มีศัตรูในระยะล่าเงา');return false;}p.x=t.x-35;p.y=t.y;safeLanding(p);p.destination=null;p.unstoppable=1.1;p.channel=.95;damage(t,(110+p.level*15)*p.spell,p);game.casts ||= [];for(let n=1;n<=3;n++)game.casts.push({id:game.nextId++,source:p.id,at:game.time+n*.27,follow:true,radius:170,amount:(110+p.level*15)*p.spell,stun:n===3?.8:0});setAction(p,'ultimate',t);effects.push({type:'ring',x:p.x,y:p.y,radius:170,color:PURPLE,life:1,max:1});}
  else if(key==='q'&&p.def.id==='sentinel'){hitCone(p,aim,185,(140+p.level*15)*p.spell);effects.push({type:'slash',x:p.x,y:p.y,tx:aim.x,ty:aim.y,radius:185,color:tint,life:.35,max:.35});setAction(p,'attack',aim);}
  else{ok=basicSkill(key,p,aim);if(ok){if(key==='w')safeLanding(p);setAction(p,key==='w'?'dash':key==='e'?'ultimate':'spell',aim);cooldown=p.cd[key]/(1-Math.min(.6,p.cdr));}}
  if(!ok)return false;p.recall=0;p.mana-=cost;p.cd[key]=cooldown*(1-Math.min(.6,p.cdr));if(p.player){tone(key==='e'?180:540,.1);syncHud();}return true;
};
function segmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,length=dx*dx+dy*dy,t=length?Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/length)):0;return Math.hypot(p.x-a.x-dx*t,p.y-a.y-dy*t);}
const basicUpdate=update;
update=function(dt){if(!game||game.paused||game.finished)return basicUpdate(dt);for(const e of game.entities.filter(e=>e.type==='hero')){e.mana??=400;e.maxMana??=400;if(!e.dead){if(e.wasDead)e.mana=e.maxMana;e.mana=Math.min(e.maxMana,e.mana+(distance(e,home(e.team))<105?90:9)*dt);}e.wasDead=e.dead;e.unstoppable=Math.max(0,(e.unstoppable||0)-dt);e.channel=Math.max(0,(e.channel||0)-dt);if(e.qCombo===1&&game.time>=e.comboUntil){e.qCombo=0;e.cd.q=Math.max(0,e.comboReadyAt-game.time);}}
  basicUpdate(dt);if(game.finished)return;for(const p of game.entities.filter(e=>e.dragonRangeBuff&&e.rage<=0)){p.range-=90;p.dragonRangeBuff=false;}game.strikes=(game.strikes||[]).filter(hit=>{if(hit.at>game.time)return true;const source=game.entities.find(e=>e.id===hit.source),target=game.entities.find(e=>e.id===hit.target&&!e.dead);if(source&&target&&hit.ranged){const dx=target.x-source.x,dy=target.y-source.y,d=Math.hypot(dx,dy)||1;game.projectiles ||= [];game.projectiles.push({id:game.nextId++,source:source.id,team:source.team,target:target.id,x:source.x,y:source.y,dx:dx/d,dy:dy/d,remaining:1500,speed:900,damage:hit.amount,slow:hit.loreSlow,stun:hit.loreStun,splash:hit.splash||(source.def?.id==='arcanist'&&source.rage>0?75:0),color:source.def?.id==='arcanist'?'#a6ef62':source.team===0?BLUE:RED});return false;}if(source&&target&&!source.dead&&distance(source,target)<=hit.range+target.radius+35){damage(target,hit.amount,source);if(hit.silence)target.silence=Math.max(target.silence||0,hit.silence);if(hit.splash)for(const splash of game.entities.filter(e=>!e.dead&&e.team!==source.team&&e.id!==target.id&&distance(e,target)<hit.splash))damage(splash,hit.amount*.45,source);if(source.def?.id==='arcanist'&&source.rage>0)for(const splash of enemies(source,source.range+120,true).filter(e=>e.id!==target.id&&distance(e,target)<75))damage(splash,hit.amount*.45,source);}return false;});const casts=game.casts||[];game.casts=[];for(const c of casts){if(c.at>game.time){game.casts.push(c);continue;}const source=game.entities.find(e=>e.id===c.source&&!e.dead);if(!source||c.interruptible&&source.stun>0)continue;const at=c.follow?source:c;for(const t of game.entities.filter(t=>!t.dead&&t.team!==source.team&&!['tower','base'].includes(t.type)&&(c.line?segmentDistance(t,c,{x:c.tx,y:c.ty})<=c.radius+t.radius:distance(t,at)<=c.radius+t.radius))){spellDamage(t,c.amount+(c.percent||0)*t.maxHp,source);if(c.stun&&t.type==='hero')stun(t,c.stun);if(c.slow)t.slow=Math.max(t.slow||0,c.slow);if(c.silence)t.silence=Math.max(t.silence||0,c.silence);if(c.mark)t.fireMark={source:source.id,until:game.time+5};if(c.markedStun&&t.fireMark?.source===source.id&&t.fireMark.until>game.time&&t.type==='hero'){stun(t,1);t.fireMark=null;}}effects.push(c.line?{type:'breath',x:c.x,y:c.y,tx:c.tx,ty:c.ty,radius:c.radius,color:c.color||'#a6ef62',life:.5,max:.5}:{type:'ring',x:at.x,y:at.y,radius:c.radius,color:c.color||(source.team===0?BLUE:RED),life:.5,max:.5});}
  game.projectiles=(game.projectiles||[]).filter(projectile=>{const source=game.entities.find(e=>e.id===projectile.source);if(!source)return false;if(projectile.target){const t=game.entities.find(e=>e.id===projectile.target&&!e.dead);if(!t)return false;const dx=t.x-projectile.x,dy=t.y-projectile.y,d=Math.hypot(dx,dy)||1;projectile.dx=dx/d;projectile.dy=dy/d;}const step=Math.min(projectile.remaining,projectile.speed*dt),before={x:projectile.x,y:projectile.y};projectile.x+=projectile.dx*step;projectile.y+=projectile.dy*step;projectile.remaining-=step;const candidates=game.entities.filter(t=>!t.dead&&t.team!==source.team&&(projectile.target?t.id===projectile.target:!['tower','base'].includes(t.type))&&segmentDistance(t,before,projectile)<t.radius+(projectile.target?8:22));if(candidates.length){const target=candidates.sort((a,b)=>distance(a,before)-distance(b,before))[0];damage(target,projectile.damage,source);if(projectile.stun&&target.type==='hero')stun(target,projectile.stun);if(projectile.slow)target.slow=Math.max(target.slow||0,projectile.slow);if(projectile.splash)for(const t of game.entities.filter(e=>!e.dead&&e.team!==source.team&&e.id!==target.id&&distance(e,target)<projectile.splash))damage(t,projectile.damage*.5,source);return false;}return projectile.remaining>0;});
};
const basicHud=syncHud;
syncHud=function(){basicHud();if(!game)return;const p=game.player;$('manaFill').style.width=(p.mana??400)/(p.maxMana||400)*100+'%';$('manaText').textContent=Math.floor(p.mana??400)+' / '+(p.maxMana||400);$('qCharges').textContent=p.qCombo===1?'อีก 1 ครั้ง':'';};
const basicTarget=attackTarget;
attackTarget=function(e){const mode=e.remoteHuman?e.control?.targetMode:$('targetMode').value;if(mode!=='tower')return basicTarget(e);return enemies(e,e.range,true).filter(t=>t.type!=='base'||baseOpen(t.team)).sort((a,b)=>(['tower','base'].includes(a.type)?0:1)-(['tower','base'].includes(b.type)?0:1)||distance(e,a)-distance(e,b))[0];};
HEROES.find(h=>h.id==='shade').q='พุ่งเงา ×2';HEROES.find(h=>h.id==='shade').details='Q: พุ่งได้สองครั้ง ครั้งแรกยกศัตรู · E: พุ่งเข้าฟัน 4 ครั้งและต้านสตัน';HEROES.find(h=>h.id==='arcanist').details='Q: ลากเล็งลมหายใจมังกรเป็นแนวตรง · W: ระเบิดผลักศัตรู · E: โล่ ยิงเร็วขึ้น เพิ่มระยะ และรีเซ็ต Q/W 8 วินาที';HEROES.find(h=>h.id==='ranger').details='Q: ลากยิงลูกศรสามดอก · E: ยิงเร็วและแรงขึ้น 6 วินาที';HEROES.find(h=>h.id==='sentinel').details='Q: เล็งฟันด้านหน้า · E: หมุนโจมตีรอบตัวต่อเนื่อง 3 วินาที';
